static void __stdcall SaveToBuffer(::SGAMEDATA * pGame, int32_t nSaveParam, D2UnitStrc * pUnit, D2ClientStrc * pClient) {
    uint8_t charSaveBuffer[8192];
    uint32_t nSecurityCookie;
    D2SaveFileHeaderStrc* pExistingSave = GAME::Clients::GetSaveGame(pClient);
    if (pExistingSave) {
      GAME::Clients::DeleteCurrentSave(pClient);
    }

    size_t nSaveSize = 0;
    PlayerSave2::MakeSaveFile(pGame, pUnit, charSaveBuffer, (int*)&nSaveSize, 0x2000, nSaveParam, 0);
    size_t nSizeSave = nSaveSize;
    if ((int)nSaveSize <= 0) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", (void*)(int32_t)Fog::Src::ErrorManager::GetInstructionPointer(), 0xb32);
      exit(-1);
    }

    uint32_t nClientId = GAME::Clients::GetClientNo(pClient);
    GAME::Clients::CLIENT_AccumulateSaveData(nClientId, charSaveBuffer, nSizeSave, nSizeSave, 0, 0, 0);
    GAME::Clients::CLIENTS_ResetSaveTransferState(pClient);
}

// Top-level player save dispatcher. Clears UNITFLAGEX_UPDATEINV, detects if the player is currently trading (interact with another UNIT_PLAYER), then routes to SaveToBuffer (OBNet/LAN), SaveToFile (SP without BNet service), or SaveToFileBnet (BNet) based on game type and BattleNetServerService pointer.
// @sourcefile .\PLAYER\PlrSave.cpp
BOOL __fastcall SaveGameAllGameTypes(::SGAMEDATA * pGame, D2UnitStrc * pUnit, char * pCharName, BOOL bUnknown) {
    BOOL _bHasInteractInfo;
    bool bHasInteractInfo;
    D2ClientStrc* pClient;
    int nSaveResult;
    uint32_t nInteractUnitGUID;
    uint32_t clientContainer;
    uint32_t nRealm;
    eD2UnitType eInteractUnitType;
    int bSaveSucceeded;
    int bIsInteracting;
    char szAccountName[52];
    uint32_t nSecurityCookie;
    char* szCharName = pCharName;
    if (!pUnit) {
      return 0;
    }

    pUnit->eUnitFlagsEx &= ~UNITFLAGEX_UPDATEINV;
    bIsInteracting = 0;
    eInteractUnitType = UNIT_COUNT;
    _bHasInteractInfo = UNIT::SUnit::GetInteractInfo(pUnit, &eInteractUnitType, &nInteractUnitGUID);
    if (_bHasInteractInfo && eInteractUnitType == UNIT_PLAYER) {
      bIsInteracting = 1;
    }

    pClient = UNIT::SUnit::SUNIT_GetClient(pUnit, ".\\PLAYER\\PlrSave.cpp", 0xb67);
    GAME::Clients::GetAccountName(pClient, szAccountName);
    GAME::Clients::GetClientContainer(pClient, &clientContainer);
    GAME::Clients::GetRealm(pClient, &nRealm);
    bSaveSucceeded = 1;
    if (pGame->nGameType == SGAMETYPE_OBNET_HOST || pGame->nGameType == SGAMETYPE_LAN_HOST) {
      ::SGAMEDATA* pGameCopy = pGame;
      SaveToBuffer(pGameCopy, bIsInteracting, pUnit, pClient);
    } else if (BattleNetServerService) {
      nSaveResult = SaveToFileBnet(pGame, (uint32_t)szAccountName, pUnit, (uint32_t)szCharName, bIsInteracting, clientContainer, bUnknown, nRealm);
      bSaveSucceeded = nSaveResult;
    } else {
      PlayerSave::SaveToFile(pGame, pUnit, bIsInteracting, bUnknown, szCharName);
    }

    _bHasInteractInfo = bSaveSucceeded;
    return _bHasInteractInfo;
}

static void __stdcall SERVER_InitPlayer(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2ClientStrc * pClient) {
    GAME::Clients::SERVER_LinkServerPlayerUnitToClient(pClient, pUnit);
    UNIT::SUnit::SetClient(pUnit, pClient);
    char* szName = GAME::Clients::GetCharName(pClient);
    D2Common::Units::SetNameInPlayerData(pUnit, szName);
    UNIT::SUnit::SetSeed(pUnit, &pGame->pGameSeed);
    D2Common::Units::SetupUpdateFlag(pUnit, 1);
    D2UnitDataPlayerStrc* pPlayerData = D2Common::Units::GetPlayerData(pUnit);
    pPlayerData->pTradeCopyInventory = 0;
    pPlayerData->dwTradeState = 0;
    pPlayerData->nAcceptTradeTick = 0;
    pPlayerData->nAiState = 0;
}

// Creates fresh player unit for new character. Allocates unit from class ID, initializes base stats, creates starter items (potions/weapons/armor per CharStartItems.txt), sets default left/right attack skills and starting skill if present (e.g. Fire Bolt for Sorc). Notifies quests of player join. Returns unit via ppUnitOut.
static BOOL __stdcall SERVER_CreatePlayerUnit(::SGAMEDATA * pGameStrc, D2ClientStrc * pClient, D2UnitStrc * * ppUnitOut) {
    D2SkillStrc* pDVar1;
    D2SkillStrc* pStartSkill;
    int nClassIdCheck;
    GAME::Clients::SetCientFlag0x01(pClient);
    uint32_t nPlayerClassId = GAME::Clients::GetPlayerClassId(pClient);
    D2UnitStrc* pUnit = UNIT::SUnit::CreateUnit(UNIT_PLAYER, nPlayerClassId, 0, 0, pGameStrc, nullptr, 0, 0, nullptr);
    SERVER_InitPlayer(pGameStrc, pUnit, pClient);
    UNIT::SUnitMsg::SERVER_SendInitUnitPacket(pGameStrc, pUnit, pClient);
    uint8_t byAct = GAME::Clients::GetAct(pClient);
    UNIT::SUnitMsg::PLAYER_InitBaseStats(pGameStrc, pUnit, byAct);
    Player::PLAYER_CreateAllStarterItems(pUnit, pGameStrc, byAct);
    D2UnitDataPlayerStrc* pPlayerData = D2Common::Units::GetPlayerData(pUnit);
    pPlayerData->eLeftSkillId = SKILL_Attack;
    pPlayerData->eRightSkillId = SKILL_Attack;
    if (!byAct && pUnit) {
      D2CharStatsTxt* pCharStatsTxt;
      nClassIdCheck = pUnit->nClassId;
      if (nClassIdCheck >= 0 && nClassIdCheck < D2Common::ITEMS::Items::sgptDataTable->nTxtCharStatsSize) {
        pCharStatsTxt = D2Common::ITEMS::Items::sgptDataTable->pTxtCharStats + nClassIdCheck;
        if (pCharStatsTxt && pCharStatsTxt->StartSkill) {
          pDVar1 = D2Common::Skills::SKILLS_GetSkillByEnum(pUnit, (int)pCharStatsTxt->StartSkill);
          if (pDVar1) {
            SKILLS::SkillsServer::Server_SelectSkill(pUnit, 0, (int)pCharStatsTxt->StartSkill, -1);
            pPlayerData->eRightSkillId = (int)pCharStatsTxt->StartSkill;
          }
        }
      }
    }

    Quests::QUESTS::QUEST_OnPlayerJoinGame(pGameStrc, pUnit, 1);
    *ppUnitOut = pUnit;
    return 0;
}

// Parses and validates a legacy/single-player save-game character block when a client loads into the game, then instantiates the player unit. Copies the 0x82-byte save header from param_1_00, checks the magic (0xAA55AA55) and size, validates the char name matches the client's, and enforces expansion/hardcore/difficulty-progression rules (calling GuardStack with a distinct error code on each rejection). On success it applies guild tag/name/info and weapon-swap/class flags to the client, sets the act, restores the single-player init seed when applicable, creates the UNIT_PLAYER unit (CreateUnit + SERVER_InitPlayer) and sends the init-unit packet, then writes out skill-tab/skill-list counts, remaps the 8 hotkey + left/right skill-hotkey entries, and reports the skill list size via the out-params. *pdwParam signals a Battle.net redirect/abort path. Stack-guarded.
